// TestCategorySQLMatchesGo checks that sport.Condition selects exactly the
// activities sport.CategoryOf assigns, for all sports of a real export plus
// edge cases.
func TestCategorySQLMatchesGo(t *testing.T) {
	ctx := context.Background()
	s := newStore(t)
	combos := [][2]string{
		{"cycling", "gravel_cycling"}, {"cycling", "generic"}, {"cycling", "indoor_cycling"},
		{"cycling", "virtual_activity"}, {"cycling", "e_bike_mountain"}, {"e_biking", "generic"},
		{"running", "generic"}, {"running", "tabata"}, {"hiking", "generic"}, {"walking", "generic"},
		{"snowshoeing", "generic"}, {"fitness_equipment", "elliptical"}, {"training", "strength_training"},
		{"training", "yoga"}, {"rowing", "indoor_rowing"}, {"rowing", "generic"}, {"alpine_skiing", "generic"},
		{"swimming", "open_water"}, {"stand_up_paddleboarding", "generic"}, {"", ""},
	}
	want := map[string]map[int64]bool{}
	for i, c := range combos {
		rec := recording(fmt.Sprintf("fit:1:1:%d", i), "x", 1)
		rec.Activity.Sport, rec.Activity.SubSport = c[0], c[1]
		id, _, err := s.SaveRecording(ctx, rec)
		if err != nil {
			t.Fatal(err)
		}
		cat := sport.CategoryOf(c[0], c[1]).ID
		if want[cat] == nil {
			want[cat] = map[int64]bool{}
		}
		want[cat][id] = true
	}
	total := 0
	for _, cat := range sport.Categories {
		list, err := s.List(ctx, ListFilter{Category: cat.ID})
		if err != nil {
			t.Fatalf("%s: %v", cat.ID, err)
		}
		got := map[int64]bool{}
		for _, a := range list {
			got[a.ID] = true
		}
		if fmt.Sprint(got) != fmt.Sprint(want[cat.ID]) {
			t.Errorf("%s: SQL %v, Go %v", cat.ID, got, want[cat.ID])
		}
		total += len(list)
	}
	if total != len(combos) {
		t.Errorf("categories must partition all activities: %d of %d", total, len(combos))
	}
}
